import {CONTENT} from './content-catalog.mjs';
import {openAdminFeedback} from './admin-feedback.mjs';
import {feedbackBadge} from './feedback.mjs';
import {feedbackStatuses,feedbackCategories} from './feedback-state.mjs';
import {$,$$,icon,brand,addOverlayShell,openDialog as renderDialog,closeDialog,toast,guard,escapeHTML,money,dateTime,api} from './ui.js';

const modules=[['overview','运营总览','chart'],['users','账号管理','users'],['products','商品与价格','bag'],['orders','订单与收款','order'],['entitlements','权益明细','crown'],['codes','卡密管理','card'],['invites','邀请活动','gift'],['feedback','用户反馈','edit'],['content','页面内容','edit'],['system','系统状态','settings'],['audit','操作记录','history']];
const V6='/api/v6',V7='/api/v7';
let me,active='overview',pageState={},busy=false,viewRevision=0,cardBatchBusy=false,unexportedCardCodes=null,userDetailRevision=0;
const manualGrantRequests=new Map(),manualGrantBusy=new Set();let userReferralRequestRevision=0;
const refundBusy=new Set();
let pageEdit=null;
function pageFormSnapshot(form){return JSON.stringify([...new FormData(form)]);}
function watchPageForm(form,label){pageEdit={form,label,saved:pageFormSnapshot(form),pending:false};}
function hasUnsavedPageEdits(){return Boolean(pageEdit?.form.isConnected&&pageFormSnapshot(pageEdit.form)!==pageEdit.saved);}
function canLeavePageForm(){
 if(pageEdit?.pending){toast('正在保存，请等待结果后再切换页面。');return false;}
 return !hasUnsavedPageEdits()||confirm(`${pageEdit.label}尚有未保存的修改。离开会放弃这些修改，是否继续？`);
}
function beginPageSave(form){if(pageEdit?.form!==form||pageEdit.pending)return false;pageEdit.pending=true;return true;}
function finishPageSave(form,savedSnapshot){
 if(pageEdit?.form!==form)return;
 pageEdit.pending=false;
 if(savedSnapshot!==undefined)pageEdit.saved=savedSnapshot;
}
function openDialog(title,content,drawer=false){userDetailRevision++;renderDialog(title,content,drawer);}
function confirmCardAction(message){
 return new Promise(resolve=>{
  openDialog('确认卡密操作',`<p>${html(message)}</p><div class="button-row"><button class="button secondary" id="cancelCardAction">取消</button><button class="button primary" id="confirmCardAction">确认继续</button></div>`);
  const dialog=$('#dialog');let settled=false;
  const finish=confirmed=>{if(settled)return;settled=true;dialog.removeEventListener('close',cancel);closeDialog();resolve(confirmed);};
  const cancel=()=>finish(false);
  dialog.addEventListener('close',cancel);
  $('#cancelCardAction').onclick=cancel;$('#confirmCardAction').onclick=()=>finish(true);
  $('#cancelCardAction').focus();
 });
}
const state={userQ:'',userStatus:'',userPage:1,orderPage:1,orderFilters:{},refQ:'',refStatus:'',refPage:1,refNeedsReview:false,feedbackQ:'',feedbackStatus:'',feedbackCategory:'',feedbackPage:1};
const html=v=>escapeHTML(v==null?'':String(v));
const labelStatus=s=>({superadmin:'超级管理员',active:'启用',disabled:'停用',banned:'封禁',pending:'待支付',paid:'已支付',refunded:'已退款',closed:'已关闭',partial_review:'部分退款待复核',refund_pending:'退款待确认',legacy_unavailable:'历史渠道待核对',issued:'未使用',redeemed:'已兑换',void:'已作废',expired:'已过期',rewarded:'已发放',eligible:'待发放',pending_review:'待核验',revoked:'已撤销',ineligible:'未达条件'})[s]||s||'—';
const featureNames=Object.fromEntries(Object.values(CONTENT.products).map(p=>[p.feature,p.name]));const featureLabel=value=>featureNames[value]||value||'—';
const machineNames=Object.fromEntries(Object.entries(CONTENT.machines).map(([id,m])=>[id,m.name]));const machineLabel=value=>machineNames[value]||value||'—';
const referralStatuses={pending:'等待资格确认',held:'待人工核验',rewarded:'已发放',revoked:'已撤销',capped:'达到月度上限'};
const referralBadge=s=>`<span class="tag ${s==='rewarded'?'green':['pending','held','capped'].includes(s)?'amber':s==='revoked'?'red':''}">${html(referralStatuses[s]||s||'—')}</span>`;
const badge=(s,extra='')=>`<span class="tag ${extra||(['active','paid','redeemed','rewarded'].includes(s)?'green':['disabled','pending','eligible','pending_review','expired'].includes(s)?'amber':['banned','void','revoked','ineligible'].includes(s)?'red':'')}">${html(labelStatus(s))}</span>`;
const card=(title,body,sub='')=>`<section class="admin-card"><div class="card-heading"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div></div>${body}</section>`;
const title=(h,p,actions='')=>`<div class="admin-title"><div><h1>${h}</h1><p>${p}</p></div>${actions}</div>`;
const field=(label,name,type='text',attrs='')=>`<label class="field">${label}<input name="${name}" type="${type}" ${attrs}></label>`;
function nav(){return modules.map(([id,name,glyph])=>`<button type="button" data-module="${id}" class="${active===id?'active':''}" aria-current="${active===id?'page':'false'}">${icon(glyph)}<span>${name}</span></button>`).join('');}
function shell(){return `<div class="admin-shell"><aside class="admin-sidebar">${brand('/login.html')}<span class="admin-side-label">运营工作台</span><label class="admin-mobile-menu">管理模块<select id="adminModule" aria-label="选择管理模块">${modules.map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label><nav class="admin-nav" aria-label="管理模块">${nav()}</nav><div class="admin-sidebar-bottom"><p>管理操作均由服务端校验并记入审计。</p><div class="admin-user">${icon('shield')}<span>${html(me.custom_id||me.phone||'超级管理员')}<small>超级管理员</small></span></div></div></aside><div class="admin-content"><header class="admin-topbar"><span>工作台 <span class="slash">/</span> <b id="crumb">运营总览</b></span><div class="admin-top-actions"><span>${html(me.custom_id||'')}</span><a href="/play.html">返回玩法 ↗</a></div></header><main class="admin-body" id="adminBody"></main></div></div>`;}
function setBody(content){$('#adminBody').innerHTML=content;
 if(['users','orders','feedback'].includes(active))for(const table of $$('#adminBody table')){table.classList.add('mobile-records');const headers=[...table.querySelectorAll('thead th')].map(cell=>cell.textContent);for(const row of table.querySelectorAll('tbody tr'))[...row.cells].forEach((cell,i)=>{cell.dataset.label=headers[i]||'';});}
 bindCommon();}
function loading(text='正在读取真实数据…'){return `<div class="admin-state"><span class="spinner"></span>${text}</div>`;}
function errorState(e,retry){return `<div class="admin-state error"><p>${html(e.message||'读取失败')}</p>${retry?'<button class="button compact" data-retry>重试</button>':''}</div>`;}
function empty(text){return `<div class="admin-state">${html(text)}</div>`;}
function pageNav(page,pages,total,attr){return `<div class="table-foot"><span>共 ${Number(total)||0} 条 · 第 ${Number(page)||1} / ${Number(pages)||1} 页</span><span class="pager"><button class="button compact" data-page="prev" data-kind="${attr}" ${page<=1?'disabled':''}>上一页</button><button class="button compact" data-page="next" data-kind="${attr}" ${page>=pages?'disabled':''}>下一页</button></span></div>`;}
function table(head,rows,emptyText='暂无记录'){return `<div class="table-scroll"><table><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${head.length}">${html(emptyText)}</td></tr>`}</tbody></table></div>`;}
function bindCommon(){
  $$('#adminBody [data-module]').forEach(b=>b.onclick=()=>render(b.dataset.module));
  $$('#adminBody [data-retry]').forEach(b=>b.onclick=()=>render(active));
  $$('#adminBody [data-page]').forEach(b=>b.onclick=()=>{const key=b.dataset.kind;if(b.dataset.page==='prev')state[key]--;else state[key]++;render(active);});
  $$('#adminBody [data-user-detail]').forEach(b=>b.onclick=()=>guard(()=>showUser(b.dataset.userDetail)));
  $$('#adminBody [data-batch]').forEach(b=>b.onclick=()=>guard(()=>showBatch(b.dataset.batch)));
  $$('#adminBody [data-reconcile]').forEach(b=>b.onclick=()=>guard(()=>reconcile(b.dataset.reconcile,b)));
  $$('#adminBody [data-refund-detail]').forEach(b=>b.onclick=()=>guard(()=>showRefund(b.dataset.refundDetail)));
}
async function render(key){if(cardBatchBusy||unexportedCardCodes){toast(cardBatchBusy?'卡密正在生成，请等待生成完成。':'请先下载并保存本次生成的卡密。');return;}if(!canLeavePageForm())return;pageEdit=null;active=key;const revision=++viewRevision;const mod=modules.find(x=>x[0]===key);$('#crumb').textContent=mod?.[1]||'运营总览';$$('.admin-nav [data-module]').forEach(b=>{b.classList.toggle('active',b.dataset.module===key);b.setAttribute('aria-current',b.dataset.module===key?'page':'false');});if($('#adminModule'))$('#adminModule').value=key;setBody(loading());try{await ({overview,users:accounts,products,orders,entitlements,codes,invites,feedback:feedbackInbox,content,system,audit}[key]||overview)(revision);}catch(e){if(revision!==viewRevision)return;setBody(`${title(mod?.[1]||'管理模块','读取实时业务数据时遇到问题。')}${card('无法读取',errorState(e,true))}`);}}

async function overview(revision){
 const d=await api(`${V7}/admin/overview`);if(revision!==viewRevision)return;
 const metricHtml=[['注册账号',d.accounts,'累计注册'],['有效专业会员',d.entitlement_sources?.feature_totals?.pro,'正常普通账号，来源去重'],['有效星空皮肤',d.entitlement_sources?.feature_totals?.cosmic,'正常普通账号，来源去重']].map(([label,value,note])=>`<article class="metric-card"><span class="metric-label">${label}</span><strong>${html(value??'—')}</strong><small>${note} · 截至 ${dateTime(d.as_of)}</small></article>`).join('');
 const trend=d.trend||[],max=Math.max(1,...trend.flatMap(x=>[Number(x.registrations)||0,Number(x.draws)||0]));const points=key=>trend.map((x,i)=>`${trend.length<2?0:i/(trend.length-1)*100},${48-(Number(x[key])||0)/max*42}`).join(' ');const chart=trend.length?`<svg class="trend-chart" viewBox="0 0 100 52" preserveAspectRatio="none" aria-label="最近七天注册与抽取数量趋势"><polyline points="${points('registrations')}" fill="none" stroke="#8172c5" stroke-width="1.3" vector-effect="non-scaling-stroke"/><polyline points="${points('draws')}" fill="none" stroke="#70a4b3" stroke-width="1.3" vector-effect="non-scaling-stroke"/></svg><div class="trend-labels">${trend.map(x=>`<span>${html(x.date)}</span>`).join('')}</div>`:empty('最近七天暂无趋势数据');
 const latest=trend.at(-1),latestSummary=latest?`<div class="funnel-grid latest-summary"><div class="funnel-item"><b>${html(latest.registrations??'—')}</b><span>新注册</span></div><div class="funnel-item"><b>${html(latest.draws??'—')}</b><span>正式抽取</span></div></div>`:empty('暂无日汇总数据');
 const usage=d.usage||{},cohort=usage.cohort||{},rate=value=>value==null||!Number.isFinite(Number(value))?'—':`${Number(value).toFixed(1)}%`;
 const stages=[['去重体验身份',cohort.experienced,'基准'],['新注册',cohort.registered,rate(cohort.registration_rate)],['皮肤预览',cohort.previewed,rate(cohort.preview_rate)],['支付',cohort.paid,rate(cohort.payment_rate)]].map(([label,count,pct],index)=>`<div class="cohort-step"><span class="cohort-step-label">${label}</span><strong>${html(count??'—')}</strong><small>${index===0?'转化基准':`占上一阶段 ${html(pct)}`}</small></div>`).join('');
 const sourceNames={paid:'付费',card:'卡密兑换',referral:'邀请奖励',manual:'人工授予',legacy:'历史来源',other:'其他'};const sourceKeys=Object.keys(sourceNames),sources=d.entitlement_sources||{},accountSources=sources.accounts||{},featureSources=sources.features||{},sourceRows=sourceKeys.map(key=>`<tr><td>${sourceNames[key]}</td><td>${html(accountSources[key]??'—')}</td><td>${html(featureSources.pro?.[key]??'—')}</td><td>${html(featureSources.cosmic?.[key]??'—')}</td></tr>`).join('');
 const f=d.funnel||{},cumulative=[['注册',f.registrations],['正式抽取',f.draws],['皮肤预览',f.skin_previews],['付费订单',f.paid_orders]].map(([label,count])=>`<div class="funnel-item"><b>${html(count??'—')}</b><span>${label}</span></div>`).join('');const r=d.referrals||{};
 const finance=[['支付宝已支付',d.alipay_paid_cents],['已记录退款',d.alipay_refund_cents],['本地净额',d.alipay_net_cents]].map(([label,cents])=>`<div class="finance-item"><span>${label}</span><strong>${cents==null?'—':money(cents)}</strong></div>`).join('');
 const attentionItems=[['已付未开通',d.order_issues?.missing_grant,'missing_grant'],['退款待确认',d.order_issues?.refund_pending,'refund_pending'],['部分退款待复核',d.order_issues?.refund_review,'refund_review'],['邀请待核验',r.needs_review,'invite_review'],['新用户反馈',d.feedback?.new||0,'feedback']];
 const attention=`<section class="attention-panel" aria-label="待处理事项"><div class="attention-heading"><div><h2>待处理事项</h2><p>先处理影响用户权益的问题</p></div><span>${attentionItems.every(([,count])=>count===0)?'当前无待处理事项':'点击查看对应记录'}</span></div><div class="attention-grid">${attentionItems.map(([label,count,key])=>`<button type="button" data-attention="${key}" class="attention-item ${Number(count)>0?'has-issues':''}"><span>${label}</span><strong>${html(count??'—')}</strong><small>查看记录 ↗</small></button>`).join('')}</div></section>`;
 const textNote=(label,value)=>`<div class="overview-copy"><b>${label}</b><p>${html(value||'—')}</p></div>`;
 setBody(`${title('运营总览','真实账号、体验转化与订单状态。',`<button class="button" data-module="invites">${icon('gift')} 邀请活动</button>`)}${attention}<div class="metric-grid overview-top-metrics">${metricHtml}</div><div class="admin-grid">${card('最近七天趋势',`${chart}<div class="chart-key"><span><i class="purple-dot"></i>注册</span><span><i class="teal-dot"></i>抽取</span></div>`,'服务端汇总，按本地日期')}${card('最近一天',latestSummary,latest?html(latest.date):'暂无日汇总数据')}</div>${card('近 30 日实际体验与同群体转化',`<div class="usage-meta"><span>统计区间：${html(dateTime(usage.since))} 至 ${html(dateTime(usage.until))}</span><span>活跃账号：${html(usage.active_accounts??'—')}</span><span>未登录体验身份：${html(usage.guest_scopes??'—')} <small>按浏览器身份计数，不等于人数</small></span></div><div class="cohort-steps">${stages}</div><details class="overview-details"><summary>统计口径与限制说明</summary><div class="usage-notes">${textNote('统计口径',usage.definition)}${textNote('限制说明',usage.limitations)}</div></details>`,'同一体验群体按正式抽取 → 新注册 → 皮肤预览 → 支付去重；已有账号和超级管理员不计入转化分母。')}${card('权益来源账号数',table(['来源','全部权益账号','专业功能','星空皮肤'],sourceRows,'暂无权益来源数据')+`<details class="overview-details"><summary>权益来源统计说明</summary><div class="source-definition">${html(sources.definition||'—')}</div></details>`,'有效、未撤销且未过期的普通账号；来源与权益可能重叠，不能相加。')}${card('累计业务量',`<div class="funnel-grid">${cumulative}</div>`,'累计总量，不代表体验转化')}${card('支付宝金额',`<div class="finance-grid">${finance}</div><p class="admin-bottom-note">金额为服务端本地已确认订单与已记录退款计算，不代表支付宝结算到账。</p>`)}<div class="metric-grid small-metrics">${[['邀请已发放',r.rewarded],['邀请待处理',r.pending],['邀请已撤销',r.revoked],['权益已撤销',d.order_issues?.revoked_grant]].map(([label,value])=>`<article class="metric-card"><span class="metric-label">${label}</span><strong>${html(value??'—')}</strong></article>`).join('')}</div>`);
 $$('#adminBody [data-attention]').forEach(button=>button.onclick=()=>{const key=button.dataset.attention;if(key==='feedback'){state.feedbackStatus='new';state.feedbackPage=1;render('feedback');}else if(key==='invite_review'){state.refNeedsReview=true;state.refStatus='';state.refQ='';state.refPage=1;render('invites');}else{state.orderFilters={issue:key};state.orderPage=1;render('orders');}});
}

async function feedbackInbox(revision){
 const params=new URLSearchParams({status:state.feedbackStatus,category:state.feedbackCategory,q:state.feedbackQ,page:String(state.feedbackPage)});
 const d=await api(`${V7}/admin/feedback?${params}`);if(revision!==viewRevision)return;state.feedbackPage=d.page;
 const options=(values,selected)=>Object.entries(values).map(([key,label])=>`<option value="${key}" ${key===selected?'selected':''}>${html(label)}</option>`).join('');
 const rows=d.items.map(t=>`<tr><td>${feedbackBadge(t.status)}</td><td><b class="feedback-inbox-preview">${html(t.content.slice(0,100))}${t.content.length>100?'…':''}</b><small>${html(feedbackCategories[t.category])} · ${html(t.id)}</small></td><td>${html(t.account)}</td><td>${html(dateTime(t.created_at))}</td><td><button type="button" class="text-button" data-feedback="${html(t.id)}">查看 / 回复</button></td></tr>`).join('');
 const totals=Object.entries(feedbackStatuses).map(([key,label])=>`<span class="tag">${label} ${Number(d.counts[key])||0}</span>`).join(' ');
 setBody(`${title('用户反馈','收集体验问题与升级建议，公开回复与内部备注分别保存。')}<div class="button-row">${totals}</div><form id="feedbackFilter" class="filter-row"><label class="search-box">${icon('search')}<input name="q" maxlength="200" value="${html(state.feedbackQ)}" placeholder="搜索内容、反馈编号、联系邮箱"></label><select name="status" aria-label="反馈状态"><option value="">全部状态</option>${options(feedbackStatuses,state.feedbackStatus)}</select><select name="category" aria-label="反馈类型"><option value="">全部类型</option>${options(feedbackCategories,state.feedbackCategory)}</select><button class="button compact">查询</button></form>${card('反馈收件箱',table(['处理状态','反馈内容','提交人','提交时间','操作'],rows,'暂时没有符合条件的反馈')+pageNav(d.page,d.pages,d.total,'feedbackPage'))}`);
 $('#feedbackFilter').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);state.feedbackQ=String(f.get('q')||'').trim();state.feedbackStatus=String(f.get('status')||'');state.feedbackCategory=String(f.get('category')||'');state.feedbackPage=1;render('feedback');};
 $$('#adminBody [data-feedback]').forEach(button=>button.onclick=()=>guard(()=>openAdminFeedback(button.dataset.feedback,()=>{if(active==='feedback')render('feedback');})));
}

async function accounts(revision){const p=new URLSearchParams({q:state.userQ,status:state.userStatus,page:String(state.userPage),page_size:'25'});const d=await api(`/api/admin/users?${p}`);if(revision!==viewRevision)return;state.userPage=d.page;const rows=(d.users||[]).map(u=>`<tr><td><b>${html(u.email||u.custom_id||`账号 ${u.id}`)}</b><small>ID ${html(u.id)}</small></td><td>${html(u.custom_id||"—")}</td><td>${badge(u.status)}</td><td>${u.role==='superadmin'?badge('superadmin','purple'):'普通用户'}</td><td>${html(dateTime(u.created_at))}</td><td><button class="text-button" data-user-detail="${html(u.id)}">详情 / 权益</button></td></tr>`).join('');setBody(`${title('账号管理','搜索真实账号并查看订单与权益来源。')}<form class="filter-row" id="userFilter"><label class="search-box">${icon('search')}<input name="q" value="${html(state.userQ)}" placeholder="搜索邮箱、账号 ID 或编号"></label><select name="status"><option value="">全部状态</option>${['active','disabled','banned'].map(s=>`<option value="${s}" ${s===state.userStatus?'selected':''}>${labelStatus(s)}</option>`).join('')}</select><button class="button compact">查询</button></form>${card('账号列表',table(['邮箱 / 账号','账号 ID','状态','角色','注册时间','管理操作'],rows,'没有符合条件的账号')+pageNav(d.page,d.pages,d.total,'userPage'))}`);
 $('#userFilter').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.currentTarget);state.userQ=String(fd.get('q')||'').trim();state.userStatus=String(fd.get('status')||'');state.userPage=1;render('users');};}
function grantSourceAction(x){const id=x.manual_grant_id;if(x.revoked||id==null||!Number.isSafeInteger(Number(id)))return '';return `<button type="button" class="text-button danger" data-revoke-grant="${html(id)}">撤销此补偿</button><form class="grant-revoke-form" data-revoke-form="${html(id)}" hidden><label class="field">撤销原因<textarea name="reason" minlength="2" maxlength="200" required rows="2"></textarea></label><p class="grant-warning">只撤销这条补偿来源；不会撤销购买、卡密或邀请奖励。</p><div class="row"><button class="button secondary compact" type="button" data-revoke-cancel>取消</button><button class="button compact" type="submit">确认撤销补偿</button></div><small class="grant-revoke-error" role="status"></small></form>`;}
function bindGrantPanel(uid,token,products){
 const host=$('#manualGrantPanel');if(!host)return;
 const pending=manualGrantRequests.get(String(uid));
 const renderPending=()=>{const request=manualGrantRequests.get(String(uid));if(!request)return;const p=request.payload;host.innerHTML=`<div class="grant-pending"><b>${request.status==='inflight'?'补偿请求正在提交':request.failureType==='rejected'?'服务端未接受该补偿请求':'上次补偿请求结果未知'}</b><p>${html(featureLabel(p.feature))} · ${html(p.days)} 天 · ${html(p.reason)}</p><small>${request.error?html(request.error):'请优先使用同一请求重试；也可刷新权益来源核对是否已生效。放弃后新请求可能造成重复补偿。'}</small><div class="row"><button type="button" class="button primary compact" data-grant-retry ${request.status==='inflight'?'disabled':''}>按原请求重试</button><button type="button" class="button secondary compact" data-grant-refresh>刷新权益明细</button><button type="button" class="text-button danger" data-grant-abandon ${request.status==='inflight'?'disabled':''}>核对后放弃并重新填写</button></div></div>`;host.querySelector('[data-grant-retry]').onclick=()=>submitManualGrant(uid,token,request.payload,host);host.querySelector('[data-grant-refresh]').onclick=()=>{if(request.status==='inflight')return;showUser(uid);};host.querySelector('[data-grant-abandon]').onclick=()=>{if(request.status==='inflight')return;if(!confirm('请先核对刚刷新的权益来源。若原补偿已生效，建立新请求可能重复延长权益。确认放弃原请求并重新填写？'))return;manualGrantRequests.delete(String(uid));showUser(uid);};};
 if(pending){renderPending();return;}
 if(!products.length){host.innerHTML='<div class="admin-state">商品目录中没有可用于补偿的权益，无法建立补偿请求。</div>';return;}
 const features=[...new Map(products.filter(p=>p.feature).map(p=>[p.feature,p])).values()];
 if(!features.length){host.innerHTML='<div class="admin-state">商品目录未提供可补偿的权益类型。</div>';return;}
 host.innerHTML=`<form class="grant-form" id="manualGrantForm"><p>将新增一条独立的管理补偿来源，并按当前权益顺延；不会覆盖账号的总到期日。</p><label class="field">补偿权益<select name="feature" required>${features.map(p=>`<option value="${html(p.feature)}">${html(p.name||p.title||featureLabel(p.feature))} · ${html(featureLabel(p.feature))}</option>`).join('')}</select></label><div class="field-row"><label class="field">期限<select name="term"><option value="30">月卡 · 30 天</option><option value="90">季卡 · 90 天</option><option value="365">年卡 · 365 天</option><option value="custom">自定义</option></select></label><label class="field grant-custom-days" hidden>自定义天数<input name="days" type="number" min="1" max="3650" value="30"></label></div><label class="field">补偿原因<textarea name="reason" minlength="2" maxlength="200" required rows="3"></textarea></label><p class="grant-form-error" role="status"></p><button class="button primary" type="submit">新增补偿权益</button></form>`;
 const form=host.querySelector('#manualGrantForm'),term=form.elements.term,daysField=host.querySelector('.grant-custom-days');term.onchange=()=>{daysField.hidden=term.value!=='custom';daysField.querySelector('input').disabled=term.value!=='custom';daysField.querySelector('input').required=term.value==='custom';};daysField.querySelector('input').disabled=true;form.onsubmit=event=>{event.preventDefault();if(token!==userDetailRevision||!$('#dialog')?.open)return;const fd=new FormData(form),reason=String(fd.get('reason')||'').trim();if(reason.length<2)return toast('请填写至少 2 字的补偿原因。');const chosenFeature=String(fd.get('feature'));if(!features.some(p=>p.feature===chosenFeature))return toast('请选择目录中实际提供的权益。');const days=fd.get('term')==='custom'?Number(fd.get('days')):Number(fd.get('term'));if(!Number.isInteger(days)||days<1||days>3650)return toast('补偿期限需为 1 至 3650 天。');let requestId;try{requestId=crypto.randomUUID();}catch{return toast('当前浏览器无法生成安全请求编号，请使用受支持的浏览器。');}submitManualGrant(uid,token,{feature:chosenFeature,days,reason,request_id:requestId},host);};
}
async function submitManualGrant(uid,token,payload,host){
 const key=String(uid),current=manualGrantRequests.get(key);if(current?.status==='inflight')return;const request=current||{payload:{...payload},status:'idle',error:''};if(current&&JSON.stringify(current.payload)!==JSON.stringify(payload))return;request.status='inflight';request.error='';manualGrantRequests.set(key,request);if(host&&token===userDetailRevision)bindGrantPanel(uid,token,[]);else if(host){const b=host.querySelector('[data-grant-retry]');if(b)b.disabled=true;const note=host.querySelector('.grant-pending>small');if(note)note.textContent='正在提交原请求，请勿重复操作。';}
 try{const d=await api(`/api/v7/admin/users/${encodeURIComponent(uid)}/grants`,request.payload);manualGrantRequests.delete(key);toast(d.grant?.already_created?'该补偿请求此前已成功创建。':'补偿权益已新增。');if(token===userDetailRevision&&viewRevision===detailViewRevision&&$('#dialog')?.open)await showUser(uid);}
 catch(error){request.status='failed';request.failureType=error.status>=400&&error.status<500?'rejected':'unknown';request.error=error.status?'HTTP '+error.status+' · '+(error.message||'请求失败'):(error.message||'请求未能确认结果。');if(token===userDetailRevision&&$('#dialog')?.open){const currentHost=$('#manualGrantPanel');if(currentHost)bindGrantPanel(uid,token,[]);}toast(`${request.error} 请按原请求重试或刷新权益明细核对。`);}
}
let detailViewRevision=0;
function referralActionButtons(record,context){if(record.status==='revoked')return '—';const id=html(record.id),buttons=[];if(record.manual_hold)buttons.push(`<button type="button" class="text-button" data-referral-action="release" data-id="${id}">解除核验</button>`);else buttons.push(`<button type="button" class="text-button" data-referral-action="hold" data-id="${id}">标记待核验</button>`);if(!record.manual_hold&&['pending','held'].includes(record.status))buttons.push(`<button type="button" class="text-button" data-referral-action="retry" data-id="${id}">重评并重试</button>`);if(record.status==='rewarded')buttons.push(`<button type="button" class="text-button danger" data-referral-action="revoke" data-id="${id}">撤销奖励</button>`);return `<div class="row referral-actions">${buttons.join(' ')}</div>${record.status==='rewarded'&&!record.manual_hold?'<small>标记待核验只做记录，不会自动撤销已发奖励。</small>':''}`;}
function referralReviewState(record){const state=record.status==='revoked'?'<span class="tag">已撤销奖励</span>':record.manual_hold?'<span class="tag amber">人工待核验</span>':record.status==='revoked'?'<span class="tag red">已撤销奖励</span>':record.reviewed_at?'<span class="tag">已解除标记</span>':'—';const details=record.review_note?`<small>${html(record.review_note)}</small>`:'';const reviewer=record.review_actor_id?` · 管理员 ID ${html(record.review_actor_id)}`:'';const reviewed=record.reviewed_at?`<small>${html(dateTime(record.reviewed_at))}${reviewer}</small>`:'';return `${state}${details}${reviewed}`;}
function reviewReferral(id,action,context=null){const labels={hold:['标记邀请待核验','暂缓尚未发放的奖励。已发放的奖励只增加人工标记，不会自动撤销。'],release:['解除邀请核验标记','服务端将重新评估账号状态、体验条件和奖励上限，不会跳过资格条件。'],retry:['重新评估并尝试发放','服务端会重新检查账号状态、体验要求与月度奖励上限；人工标记必须先解除。'],revoke:['撤销此邀请奖励','只撤销该邀请记录自身发放的奖励来源，不会撤销其他购买或卡密权益。']};const [name,description]=labels[action]||['核验邀请记录',''];const revision=viewRevision;let reviewForm=null;reasonDialog(name,description,'确认操作',async reason=>{await api(`${V7}/admin/referrals/${encodeURIComponent(id)}/review`,{action,reason});const formStillCurrent=reviewForm?.isConnected&&$('#dialog')?.open&&$('#reasonForm')===reviewForm;if(context){if(formStillCurrent&&revision===viewRevision)await showUser(context.uid);return true;}if(formStillCurrent&&revision===viewRevision&&active==='invites')await render('invites');return !formStillCurrent;});reviewForm=$('#reasonForm');}
function bindReferralActions(root,context=null){root.querySelectorAll('[data-referral-action]').forEach(button=>button.onclick=()=>reviewReferral(button.dataset.id,button.dataset.referralAction,context));}
function userDetailIsCurrent(uid,token,revision,host){return revision===viewRevision&&token===userDetailRevision&&$('#dialog')?.open&&host&&host===$('#userReferralBlock')&&host.dataset.userId===String(uid)&&host.isConnected;}
async function loadUserReferrals(uid,token,revision,page=1){const host=$('#userReferralBlock');if(!userDetailIsCurrent(uid,token,revision,host))return;const requestRevision=++userReferralRequestRevision;host.innerHTML=loading('正在读取该账号的邀请记录…');try{const d=await api(`${V7}/admin/users/${encodeURIComponent(uid)}/referrals?page=${page}&page_size=10`);if(!userDetailIsCurrent(uid,token,revision,host)||requestRevision!==userReferralRequestRevision)return;const rows=(d.records||[]).map(record=>{const isInviter=record.relationship==='inviter',other=isInviter?record.invitee_name:record.inviter_name,otherId=isInviter?record.invitee_id:record.inviter_id,holdLabel=record.manual_hold?(record.status==='rewarded'?'已发放，待人工核验':'人工暂缓发放'):'';return `<tr><td><b>#${html(record.id)}</b><small>${isInviter?'我是邀请方':'我是新用户'}</small></td><td>${html(other||'—')}<small>ID ${html(otherId)}</small></td><td>${referralBadge(record.status)}${holdLabel?`<small>${holdLabel}</small>`:''}</td><td>${html(featureLabel('pro'))} ${html(record.pro_days)} 天${record.skin_feature?`<small>${html(featureLabel(record.skin_feature))} ${html(record.skin_days)} 天</small>`:''}</td><td>${html(dateTime(record.created_at))}</td><td>${referralReviewState(record)}</td><td>${referralActionButtons(record,{uid,token,revision})}</td></tr>`;}).join('');const pager=`<div class="table-foot"><span>共 ${html(d.total??0)} 条 · 第 ${html(d.page??page)} / ${html(d.pages??1)} 页</span><span class="pager"><button type="button" class="button compact" data-user-referral-page="${Math.max(1,(d.page||page)-1)}" ${(d.page||page)<=1?'disabled':''}>上一页</button><button type="button" class="button compact" data-user-referral-page="${Math.min(d.pages||1,(d.page||page)+1)}" ${(d.page||page)>=(d.pages||1)?'disabled':''}>下一页</button></span></div>`;host.innerHTML=card('邀请记录',table(['记录 / 关系','另一方账号','状态','奖励','创建时间','人工核验','操作'],rows,'该账号暂无邀请记录')+pager,'按当前账号视角展示邀请方或新用户身份');host.querySelectorAll('[data-user-referral-page]').forEach(button=>button.onclick=()=>loadUserReferrals(uid,token,revision,Number(button.dataset.userReferralPage)));bindReferralActions(host,{uid,token,revision});}catch(error){if(!userDetailIsCurrent(uid,token,revision,host)||requestRevision!==userReferralRequestRevision)return;host.innerHTML=`${card('邀请记录',errorState(error,false))}<button type="button" class="button compact" id="retryUserReferrals">重试读取邀请记录</button>`;host.querySelector('#retryUserReferrals').onclick=()=>loadUserReferrals(uid,token,revision,page);}}
async function showUser(id){const revision=viewRevision,token=++userDetailRevision;detailViewRevision=revision;const uid=String(id);const detailPromise=api(`${V6}/admin/users/${encodeURIComponent(id)}/commerce`);const productPromise=api(`${V6}/admin/products`).then(d=>({products:d.products||[]})).catch(error=>({error}));const [d,productResult]=await Promise.all([detailPromise,productPromise]);if(revision!==viewRevision||token!==userDetailRevision)return;const u=d.user,ent=d.entitlements||{},isSelf=Number(u.id)===Number(me.id),superadmin=u.role==='superadmin',grantEligible=u.role!=='superadmin'&&u.status==='active';const sources=(ent.sources||[]).map(x=>`<tr><td>${html(featureLabel(x.feature))}</td><td>${html(x.source?.startsWith('invite:')?'邀请奖励':({card:'卡密',admin:'管理授予',online:'在线购买',legacy:'历史会员'}[x.source_kind]||x.source_kind||x.source))}</td><td>${html(x.source)}</td><td>${x.expires_at===null?'永久':dateTime(x.expires_at)}</td><td>${badge(x.revoked?'revoked':x.active?'active':'expired')} ${grantSourceAction(x)}</td></tr>`).join('');const orders=(d.orders||[]).map(o=>`<tr><td>${html(o.order_no)}</td><td>${html(o.name||o.slug||'—')}</td><td>${money(o.amount)}</td><td>${badge(o.state)}</td><td>${dateTime(o.created_at)}</td></tr>`).join('');const statusControls=u.status==='active'?`<button class="button" data-user-status="disabled">停用</button><button class="button secondary" data-user-status="banned">封禁</button>`:u.status==='disabled'?`<button class="button" data-user-status="active">恢复</button><button class="button secondary" data-user-status="banned">封禁</button>`:`<button class="button" data-user-status="active">解除封禁</button>`;const actions=!isSelf?`<div class="row">${statusControls}<button class="button secondary" id="passwordReset">强制重置密码</button></div>${superadmin?'<p class="fineprint">服务端会阻止停用最后一名有效超级管理员。</p>':''}`:'';const grants=grantEligible?`<section class="admin-card grant-admin-card"><h3>补偿权益</h3><div id="manualGrantPanel">${productResult.error?`<div class="admin-state error">${html(productResult.error.message||'无法读取商品目录')}</div>`:''}</div></section>`:`<p class="grant-ineligible">${superadmin?'超级管理员无需补偿权益。':'账号当前状态不可补偿，仅可向正常普通账号新增补偿权益。'}</p>`;renderDialog('账号详情',`<div class="account-hero"><div><h3>${html(u.email||u.custom_id||`账号 ${u.id}`)}</h3><p>ID ${html(u.id)} · ${html(u.role)} · 账号 ID：${html(u.custom_id)}</p><p>${u.email?(u.email_verified?"邮箱已验证":"邮箱待验证"):"历史账号 · 尚未绑定邮箱"}</p></div>${badge(u.status)}</div><h3>权益来源</h3>${table(['权益','来源类型','来源编号','到期','状态 / 操作'],sources,'暂无权益来源')}${grants}<section class="admin-card user-referrals-card"><h3>账号邀请记录</h3><div id="userReferralBlock" data-user-id="${html(uid)}">${loading('正在读取该账号的邀请记录…')}</div></section><h3>订单</h3>${table(['订单号','商品','金额','状态','创建时间'],orders,'暂无订单')}${actions}`,true);if(grantEligible&&(!productResult.error||manualGrantRequests.has(uid)))bindGrantPanel(uid,token,productResult.products||[]);$$('#dialogBody [data-revoke-grant]').forEach(button=>button.onclick=()=>{$(`#dialogBody [data-revoke-form="${CSS.escape(button.dataset.revokeGrant)}"]`).hidden=false;button.hidden=true;});$$('#dialogBody [data-revoke-cancel]').forEach(button=>button.onclick=()=>{const form=button.closest('form');form.hidden=true;form.previousElementSibling.hidden=false;});$$('#dialogBody [data-revoke-form]').forEach(form=>form.onsubmit=async event=>{event.preventDefault();const grantId=String(form.dataset.revokeForm),button=form.querySelector('[type=submit]'),errorNode=form.querySelector('.grant-revoke-error');if(manualGrantBusy.has(grantId))return;const reason=String(new FormData(form).get('reason')||'').trim();if(reason.length<2)return toast('请填写至少 2 字的撤销原因。');manualGrantBusy.add(grantId);button.disabled=true;errorNode.textContent='';try{await api(`/api/v7/admin/grants/${encodeURIComponent(grantId)}/revoke`,{reason});toast('该补偿来源已撤销。');if(token===userDetailRevision&&revision===viewRevision&&$('#dialog')?.open)await showUser(uid);}catch(error){errorNode.textContent=error.message||'撤销失败';}finally{manualGrantBusy.delete(grantId);if(button.isConnected)button.disabled=false;}});if(!isSelf){$$('#dialogBody [data-user-status]').forEach(b=>b.onclick=()=>changeUserStatus(u.id,b.dataset.userStatus));$('#passwordReset').onclick=()=>resetPassword(u.id);}void loadUserReferrals(uid,token,revision);}async function reasonDialog(name,description,submitLabel,onSubmit){openDialog(name,`<p>${description}</p><form id="reasonForm"><label class="field">操作原因<textarea name="reason" minlength="2" maxlength="200" required rows="3"></textarea></label><button class="button primary" type="submit">${submitLabel}</button></form>`,true);$('#reasonForm').onsubmit=async e=>{e.preventDefault();if(busy)return;const form=e.currentTarget,button=form.querySelector('[type=submit]'),reason=new FormData(form).get('reason').trim();if(reason.length<2)return toast('请填写至少 2 字的原因。');busy=true;button.disabled=true;try{const keepOpen=await onSubmit(reason);if(!keepOpen&&form.isConnected&&$('#reasonForm')===form&&$('#dialog')?.open)closeDialog();toast('已完成，操作已记录。');}catch(error){toast(error.message||'操作失败');}finally{busy=false;if(button.isConnected)button.disabled=false;}};}
function changeUserStatus(id,status){const revision=viewRevision;reasonDialog('调整账号状态',`将账号 ID ${id} 的状态改为“${labelStatus(status)}”。停用会结束现有会话。`,'确认操作',async reason=>{await api(`/api/admin/users/${id}/status`,{status,reason});if(revision===viewRevision)await render('users');});}
function resetPassword(id){reasonDialog('强制重置密码',`账号 ID ${id} 的所有现有会话将结束。临时密码只显示一次，首次登录需修改。`,'生成临时密码',async reason=>{const d=await api(`/api/admin/users/${id}/reset-password`,{reason});openDialog('临时密码 · 仅本次显示',`<p>${html(d.message||'请安全交给账号本人。关闭后不会再次显示。')}</p><input id="tempPassword" readonly value="${html(d.temporary_password)}"><button class="button" id="copyTemp">复制临时密码</button>`);$('#copyTemp').onclick=()=>navigator.clipboard.writeText(d.temporary_password).then(()=>toast('已复制')).catch(()=>toast('请手动选择并复制。'));return true;});}
async function entitlements(revision){setBody(`${title('权益明细','按账号查看有效期限和全部权益来源。')}<form class="filter-row" id="entSearch"><label class="search-box">${icon('search')}<input name="q" placeholder="先搜索账号，再查看完整权益来源" value="${html(state.userQ)}"></label><button class="button compact">搜索账号</button></form><div id="entUsers">${loading()}</div>`);$('#entSearch').onsubmit=e=>{e.preventDefault();state.userQ=new FormData(e.currentTarget).get('q').trim();state.userPage=1;render('entitlements');};await searchEntUsers(revision);}
async function searchEntUsers(revision){const p=new URLSearchParams({q:state.userQ,page:String(state.userPage),page_size:'25'}),d=await api(`/api/admin/users?${p}`);if(revision!==viewRevision)return;const rows=(d.users||[]).map(u=>`<tr><td>${html(u.email||u.custom_id||u.id)}</td><td>${html(u.custom_id||"—")}</td><td>${badge(u.status)}</td><td><button class="text-button" data-user-detail="${u.id}">查看权益来源与订单</button></td></tr>`).join('');$('#entUsers').innerHTML=card('账号权益',table(['邮箱 / 账号','账号 ID','状态','详情'],rows,'没有匹配账号')+pageNav(d.page,d.pages,d.total,'userPage'));bindCommon();}

async function products(revision){const [d,library]=await Promise.all([api(`${V6}/admin/products`),api(`${V7}/catalog`)]);if(revision!==viewRevision)return;const items=(d.products||[]).slice().sort((a,b)=>(Number(a.sort_order)||0)-(Number(b.sort_order)||0)||String(a.slug).localeCompare(String(b.slug)));const rows=items.map(p=>`<tr><td><b>${html(p.name||p.title||p.slug)}</b><small>${html(p.slug)} · ${html(p.kind==='skin'?'皮肤':p.kind==='feature'?'功能':p.kind==='machine'?'机台':p.kind)} · ${html(featureLabel(p.feature))} · 期限 ${html(p.days)} 天</small><small>适用机台：${html((p.machines||[]).map(machineLabel).join('、')||'通用')}</small></td><td>${money(p.price_cents)}</td><td>v${html(p.price_version)}</td><td>${badge(p.sale_visible?'active':'disabled',p.sale_visible?'green':'amber')}<small>${p.sale_enabled?'销售可用':'销售未开放'}</small></td><td>${html(p.sort_order??0)}</td><td>${badge(p.giftable?'active':'disabled',p.giftable?'green':'amber')}<small>${p.giftable?'允许新邀请规则选用':'新邀请规则不可选用'}</small></td><td><button class="text-button" data-metadata-edit="${html(p.slug)}">展示 / 赠送</button><br><button class="text-button" data-price-edit="${html(p.slug)}">价格</button> <button class="text-button" data-price-history="${html(p.slug)}">历史</button></td></tr>`).join('');setBody(`${title('商品与价格','内容随版本交付；下架停止新销售，紧急停用才暂停使用。已有权益和记录保留。')} ${contentLibraryMarkup(library)}${card('在线商品',table(['商品 / 权益','当前价格','价格版本','销售状态','展示顺序','邀请赠送','操作'],rows,'暂无商品'))}<p class="admin-bottom-note">“允许新邀请规则选用”只影响新发布规则，不改变已发布活动、已归因承诺、卡密或购买；需停止当前活动时请前往邀请活动关闭。</p>`);bindContentLibrary(library,revision);$$('[data-price-edit]').forEach(b=>b.onclick=()=>editProduct(items.find(p=>p.slug===b.dataset.priceEdit)));$$('[data-price-history]').forEach(b=>b.onclick=()=>guard(()=>showPriceHistory(b.dataset.priceHistory)));$$('[data-metadata-edit]').forEach(b=>b.onclick=()=>editProductMetadata(items.find(p=>p.slug===b.dataset.metadataEdit),revision));}
