async function reconcile(number,button){const revision=viewRevision;if(!confirm(`向支付服务查询订单 ${number}，并按服务端结果核对权益？`))return;button.disabled=true;try{await api(`${V6}/admin/orders/${encodeURIComponent(number)}/reconcile`,{});toast('查单完成。');if(revision===viewRevision)await render('orders');}finally{button.disabled=false;}}

async function showRefund(number){
  openDialog('订单详情 / 退款',loading('正在读取订单和退款记录…'),true);
  const token=userDetailRevision,revision=viewRevision;
  try{
    const detail=await api(`${V7}/admin/orders/${encodeURIComponent(number)}/refund`);
    if(token!==userDetailRevision||revision!==viewRevision||!$('#dialog')?.open)return;
    drawRefundDetail(detail,token,revision);
  }catch(error){
    if(token!==userDetailRevision||revision!==viewRevision||!$('#dialog')?.open)return;
    renderDialog('订单详情 / 退款',`${errorState(error,false)}<button class="button" id="refundReload">重新读取</button>`,true);
    $('#refundReload').onclick=()=>showRefund(number);
  }
}
function drawRefundDetail(detail,token,revision){
  const o=detail.order,r=detail.request,number=o.order_no;
  const stateText=o.state==='refunded'?'已确认退款':({processing:'正在核对',unknown:'结果待确认',failed:'退款未成功',succeeded:'已确认退款'}[r?.state]||'尚未申请');
  const unavailable=detail.unavailable_reason?`<p class="notice">${html(detail.unavailable_reason)}</p>`:'';
  const requestInfo=r?`<h3>退款记录</h3><p>${html(stateText)} · ${html(r.message)}</p><p class="fineprint">退款编号：${html(r.request_no)}<br>首次申请：${dateTime(r.created_at)}<br>申请原因：${html(r.reason)}</p>`:'';
  const form=detail.can_refund?`<form id="refundForm"><p>全额退回 <strong>${money(o.amount)}</strong>。确认退款后，仅撤销这笔订单的${html(featureLabel(o.feature))}时长，并重新计算有效期。其他购买、卡密和邀请奖励会保留。</p>${r?'<p class="fineprint">重试沿用原退款编号、原金额与原申请原因。</p>':'<label class="field">退款原因<textarea name="reason" minlength="2" maxlength="200" rows="3" required></textarea></label>'}<button class="button primary" type="submit">${r?'按原请求重试全额退款':'确认全额退款'} ${money(o.amount)}</button></form>`:'';
  const query=r&&o.state!=='refunded'?'<button class="button secondary" id="refundQuery">查询退款结果</button>':'';
  renderDialog('订单详情 / 退款',`<h3>${html(o.name)}</h3><p>账号：${html(o.owner)}<br>订单号：${html(number)}<br>交易号：${html(o.trade_no||'—')}<br>支付时间：${dateTime(o.paid_at)}</p><p>${badge(o.state)} · 订单金额 ${money(o.amount)} · 已确认退款 ${money(o.refund_cents)}</p>${requestInfo}${unavailable}${form}<div class="row">${query}<button class="button secondary" id="refundReload">刷新本地记录</button></div><p class="fineprint">连接中断不代表退款失败。结果待确认时请稍后查询；重复操作会使用同一笔申请。</p>`,true);
  if(form){const formNode=$('#refundForm');formNode.onsubmit=event=>{
    event.preventDefault();
    const reason=r?.reason||String(new FormData(formNode).get('reason')||'').trim();
    if(reason.length<2)return toast('请填写至少 2 字的退款原因。');
    void operateRefund(number,{action:'submit',reason,expected_amount:o.amount},token,revision);
  };}
  if(query)$('#refundQuery').onclick=()=>operateRefund(number,{action:'query',reason:'',expected_amount:o.amount},token,revision);
  $('#refundReload').onclick=()=>showRefund(number);
  if(refundBusy.has(number)||r?.processing)$$('#dialogBody button,#dialogBody textarea').forEach(b=>b.disabled=b.id!=='refundReload');
}
async function operateRefund(number,payload,token,revision){
  const current=()=>token===userDetailRevision&&revision===viewRevision&&$('#dialog')?.open;
  if(refundBusy.has(number)||!current())return;
  refundBusy.add(number);
  $$('#dialogBody button,#dialogBody textarea').forEach(b=>b.disabled=true);
  try{
    const detail=await api(`${V7}/admin/orders/${encodeURIComponent(number)}/refund`,payload);
    refundBusy.delete(number);
    if(current())drawRefundDetail(detail,token,revision);
    toast(detail.order.state==='refunded'?'退款已确认，权益已核对。':'退款尚未确认成功，请查看记录后继续查询。');
  }catch(error){
    toast(error.message||'连接中断，退款结果未知。请重新打开订单详情查询。');
  }finally{
    refundBusy.delete(number);
    if(current())$$('#dialogBody button,#dialogBody textarea').forEach(b=>b.disabled=false);
  }
}

