function readCampaignDraft(form){
 const fd=new FormData(form);
 return {name:String(fd.get('name')||'').trim(),enabled:fd.has('enabled'),pro_days:Number(fd.get('pro_days')),skin_feature:String(fd.get('skin_feature')||''),skin_days:Number(fd.get('skin_days')),monthly_cap:Number(fd.get('monthly_cap')),reward_newcomer:fd.has('reward_newcomer'),require_experience:fd.has('require_experience'),attribution_days:Number(fd.get('attribution_days')),starts_at:parseLocal(fd.get('starts_at')),ends_at:parseLocal(fd.get('ends_at')),reason:String(fd.get('reason')||'').trim()};
}
function campaignDraftError(draft,skins,proGiftable){
 if(!draft.name||draft.name.length>80)return '请填写 1 至 80 字的活动名称。';
 for(const [key,label,max] of [['pro_days','专业会员天数',3650],['skin_days','皮肤天数',3650],['monthly_cap','每月奖励上限',100],['attribution_days','归因有效天数',90]]){
  if(!Number.isInteger(draft[key])||draft[key]<1||draft[key]>max)return `${label}需为 1 至 ${max} 的整数。`;
 }
 if([draft.starts_at,draft.ends_at].some(value=>value!==null&&(!Number.isFinite(value)||value<0)))return '请填写有效的活动时间。';
 if(draft.starts_at!==null&&draft.ends_at!==null&&draft.ends_at<=draft.starts_at)return '结束时间必须晚于开始时间。';
 if(draft.enabled&&!proGiftable)return '专业功能当前不允许新邀请规则选用，请先调整商品赠送设置。';
 if(draft.enabled&&draft.skin_feature&&!skins.some(s=>s.feature===draft.skin_feature))return '当前皮肤只保留为旧活动规则；启用新版本前请更换为可赠送皮肤。';
 if(draft.reason.length<2||draft.reason.length>200)return '请填写 2 至 200 字的发布原因。';
 return '';
}
function campaignPreviewMarkup(draft,skins){
 const skinName=skins.find(s=>s.feature===draft.skin_feature)?.name||featureLabel(draft.skin_feature);
 const time=(value,empty)=>value===null?empty:Number.isFinite(value)?dateTime(value):'时间尚未填写完整';
 return `<div class="campaign-rule-preview"><p><b>${html(draft.name||'请填写活动名称')}</b> · ${draft.enabled?'开放新邀请':'停止新邀请'}</p><p>邀请人：专业功能会员 ${html(draft.pro_days)} 天</p><p>赠送皮肤：${draft.skin_feature?`${html(skinName)} ${html(draft.skin_days)} 天`:'不赠送皮肤'}</p><p>${draft.reward_newcomer?'新用户也获得相同奖励':'仅邀请人获得奖励，新用户不获赠'}</p><p>发奖条件：${draft.require_experience?'新用户注册后还需完成一次正式抽取':'完成有效新账号注册后评估资格'}</p><p>每位邀请人每月最多 ${html(draft.monthly_cap)} 次 · 首次归因保留 ${html(draft.attribution_days)} 天</p><p>活动时间：${html(time(draft.starts_at,'发布后开始'))} 至 ${html(time(draft.ends_at,'不设结束时间'))}</p><p class="fineprint">${draft.enabled?'新归因采用发布后的规则；已归因用户继续按原版本兑现。':'关闭只停止新归因；原有归因和已发奖励保持不变。'} 同一种权益按有效到期日顺延，会员与皮肤独立计算。</p></div>`;
}
function bindCampaignEditor(form,campaign,skins,proGiftable,revision){
 const submit=form.querySelector('[type=submit]'),preview=$('#campaignPreview'),errorNode=$('#campaignError'),reloadForm=$('#campaignRefresh');
 watchPageForm(form,'邀请活动');
 let publishing=false,needsRefresh=false;
 const current=()=>revision===viewRevision&&form.isConnected&&$('#campaignForm')===form;
 const refresh=()=>{if(current())preview.innerHTML=campaignPreviewMarkup(readCampaignDraft(form),skins);};
 form.addEventListener('input',refresh);form.addEventListener('change',refresh);refresh();
 reloadForm.onclick=()=>{if(current()&&!publishing)void render('invites');};
 form.onsubmit=event=>{
  event.preventDefault();
  if(!current()||publishing||$('#dialog')?.open)return;
  if(needsRefresh)return toast('请先重新读取已发布规则，核对后再编辑。');
  const body={...readCampaignDraft(form),expected_version:campaign.version},submittedSnapshot=pageFormSnapshot(form);
  const problem=campaignDraftError(body,skins,proGiftable);errorNode.textContent=problem;
  if(problem)return;
  openDialog('确认发布邀请活动',`<div id="campaignPublication">${campaignPreviewMarkup(body,skins)}<p>发布原因：${html(body.reason)}</p><p class="fineprint">将基于 v${html(campaign.version)} 发布新版本。确认后新规则才会生效。</p><p id="campaignPublishError" role="status"></p><div class="button-row"><button class="button secondary" type="button" id="campaignBack">返回修改</button><button class="button primary" type="button" id="campaignPublish">确认发布</button><button class="button secondary" type="button" id="campaignReload" hidden>重新读取已发布规则</button></div></div>`,true);
  const panel=$('#campaignPublication'),button=$('#campaignPublish'),failure=$('#campaignPublishError'),reload=$('#campaignReload');
  const panelCurrent=()=>current()&&panel.isConnected&&$('#campaignPublication')===panel&&$('#dialog')?.open;
  $('#campaignBack').onclick=()=>{if(panelCurrent())closeDialog();};
  reload.onclick=()=>{if(panelCurrent()){closeDialog();void render('invites');}};
  button.onclick=async()=>{
   if(publishing||needsRefresh||!panelCurrent()||!beginPageSave(form))return;
   publishing=true;button.disabled=true;submit.disabled=true;failure.textContent='';
   try{
    await api(`${V7}/admin/referrals/settings`,body,'PUT');
    toast('新活动版本已发布。');
    needsRefresh=true;
    finishPageSave(form,submittedSnapshot);
    if(panelCurrent()&&!hasUnsavedPageEdits()){closeDialog();await render('invites');}
    else if(current()){errorNode.textContent='新活动版本已发布，请重新读取已发布规则。';reloadForm.hidden=false;}
   }catch(error){
    const uncertain=!error.status||error.status>=500;
    needsRefresh=uncertain||error.status===409;
    const message=uncertain?'发布结果尚未确认，请先重新读取已发布规则核对，避免重复发布。':error.message||'发布未成功，请核对表单。';
    if(panelCurrent()){failure.textContent=message;reload.hidden=!needsRefresh;}
    if(current()){errorNode.textContent=message;reloadForm.hidden=!needsRefresh;}
   }finally{
    publishing=false;finishPageSave(form);
    if(button.isConnected)button.disabled=needsRefresh;
    if(submit.isConnected)submit.disabled=false;
   }
  };
 };
}
